import fs from "fs";
import path from "path";

const SLUG = "business-admin";
const OUT = path.resolve(process.cwd(), `${SLUG}-instruction.json`);

type LN = { n: string; g: string; b: string; c1n: string; c1e: string; c1m: string; c2n: string; c2e: string; c2m: string; mk: string; mc: string; mt: string; ex: string; fq: string; sc: string; dur: number };
type UN = { name: string; goal: string; pk: string[]; ek: string[]; kc: string[]; ls: LN[]; labTitle: string; labScenario: string; labCriterion: string; lq: Array<{ kind: "diagnostic"|"decision"|"application"|"analysis"|"connection"; p: string; r: string; o: string; pts: number }>; eq: Array<{ p: string; ch: string[]; ci: number; ex: string; d: 1|2|3 }> };
type ST = { name: string; goal: string; bf: "remember"|"understand"|"apply"|"analyze"|"evaluate"|"create"; sq: Array<{ p: string; ch: string[]; ci: number; ex: string; d: 1|2|3 }>; us: UN[] };
type LV = { name: string; goal: string; bf: "remember"|"understand"|"apply"|"analyze"|"evaluate"|"create"; lq: Array<{ p: string; ch: string[]; ci: number; ex: string; d: 1|2|3 }>; sts: ST[] };

function lesson(n:string,g:string,b:string,c1n:string,c1e:string,c1m:string,c2n:string,c2e:string,c2m:string,mk:string,mc:string,mt:string,ex:string,fq:string,sc:string,dur=25):LN{return{n,g,b,c1n,c1e,c1m,c2n,c2e,c2m,mk,mc,mt,ex,fq,sc,dur};}
function mcq(p:string,ch:string[],ci:number,ex:string,d:1|2|3=2):{p:string;ch:string[];ci:number;ex:string;d:1|2|3}{return{p,ch,ci,ex,d};}
function labQ(kind:"diagnostic"|"decision"|"application"|"analysis"|"connection",p:string,r:string,o:string,pts:number){return{kind,p,r,o,pts};}

function buildLesson(ln: LN, li: number, unitCode: string, totalInUnit: number) {
  const prev = li > 0 ? [`${unitCode}.${li}`] : [];
  const next = li < totalInUnit - 1 ? [`${unitCode}.${li + 2}`] : [];
  return {
    lesson_index: li + 1,
    name: ln.n,
    goal: ln.g,
    bridge_sentence: ln.b,
    prerequisite_lessons: prev,
    enables_lessons: next,
    concepts: [
      { name: ln.c1n, explanation: ln.c1e, mastery_criterion: ln.c1m, weight: 2 },
      { name: ln.c2n, explanation: ln.c2e, mastery_criterion: ln.c2m, weight: 1 },
    ],
    common_mistakes: [{ mistake: ln.mk, correction: ln.mc, treatment: ln.mt, severity: "major" as const }],
    yemeni_examples: [ln.ex],
    final_check_question: ln.fq,
    session_complete_criterion: ln.sc,
    estimated_duration_minutes: ln.dur,
  };
}

function buildUnit(u: UN, li: number, si: number, ui: number) {
  const unitCode = `${li}.${si}.${ui}`;
  const lessonObjects = u.ls.map((ln, idx) => buildLesson(ln, idx, unitCode, u.ls.length));
  const lab = {
    lab_index: 1,
    title: u.labTitle,
    scenario: u.labScenario,
    mastery_criterion: u.labCriterion,
    questions: u.lq.map((q, qi) => ({ question_index: qi + 1, kind: q.kind, prompt: q.p, rubric: q.r, solution_outline: q.o, points: q.pts })),
  };
  const examQs = u.eq.map((q, qi) => ({ question_index: qi + 1, kind: "mcq" as const, prompt: q.p, choices: q.ch, correct_index: q.ci, explanation: q.ex, difficulty: q.d }));
  return {
    unit_index: ui,
    name: u.name,
    goal: u.goal,
    prerequisite_units: u.pk,
    enables_units: u.ek,
    key_concepts: u.kc,
    lessons: lessonObjects,
    labs: [lab],
    exam_questions: examQs,
  };
}

function buildStage(st: ST, li: number, si: number) {
  const stageCode = `${li}.${si}`;
  return {
    stage_index: si,
    name: st.name,
    goal: st.goal,
    bloom_focus: st.bf,
    exam: { pass_threshold_percent: 70 },
    stage_exam_questions: st.sq.map((q, qi) => ({ question_index: qi + 1, kind: "mcq" as const, prompt: q.p, choices: q.ch, correct_index: q.ci, explanation: q.ex, difficulty: q.d })),
    units: st.us.map((u, ui) => buildUnit(u, li, si, ui + 1)),
  };
}

function buildLevel(lv: LV, li: number) {
  return {
    level_index: li,
    name: lv.name,
    goal: lv.goal,
    bloom_focus: lv.bf,
    exam: { pass_threshold_percent: 70, time_limit_minutes: 90 },
    level_exam_questions: lv.lq.map((q, qi) => ({ question_index: qi + 1, kind: "mcq" as const, prompt: q.p, choices: q.ch, correct_index: q.ci, explanation: q.ex, difficulty: q.d })),
    stages: lv.sts.map((st, si) => buildStage(st, li, si + 1)),
  };
}

function buildExamBanks(levels: LV[]) {
  const unitBanks: Record<string, unknown> = {};
  const stageBanks: Record<string, unknown> = {};
  const levelBanks: Record<string, unknown> = {};
  levels.forEach((lv, li) => {
    const lIdx = li + 1;
    levelBanks[String(lIdx)] = { variants: [lv.lq.map(q => ({ kind: "mcq", prompt: q.p, choices: q.ch, correct_index: q.ci, explanation: q.ex, difficulty: q.d }))] };
    lv.sts.forEach((st, si) => {
      const sc = `${lIdx}.${si + 1}`;
      stageBanks[sc] = { variants: [st.sq.map(q => ({ kind: "mcq", prompt: q.p, choices: q.ch, correct_index: q.ci, explanation: q.ex, difficulty: q.d }))] };
      st.us.forEach((u, ui) => {
        const uc = `${sc}.${ui + 1}`;
        unitBanks[uc] = { variants: [u.eq.map(q => ({ kind: "mcq", prompt: q.p, choices: q.ch, correct_index: q.ci, explanation: q.ex, difficulty: q.d }))] };
      });
    });
  });
  return { unit_banks: unitBanks, stage_banks: stageBanks, level_banks: levelBanks };
}

